access_token = apis.spotify.login(username='as_moore@gmail.com', password='%oxCE]q')['access_token']
liked_playlists=[]
i=0
while True:
    page = apis.spotify.show_liked_playlists(access_token=access_token, page_index=i, page_limit=20, sort_by='-liked_at')
    print('liked_playlists page', i, 'items', len(page) if page else 0)
    if not page:
        break
    liked_playlists.extend(page)
    i += 1
print('total liked playlists', len(liked_playlists))
playlist_ids = [p['playlist_id'] for p in liked_playlists]
print('playlist_ids', playlist_ids)
# gather songs in those playlists
song_meta = {}  # song_id -> {title, artists}
for pid in playlist_ids:
    pl = apis.spotify.show_playlist(playlist_id=pid, access_token=access_token)
    print('playlist', pid, 'title', pl.get('title'), 'songs', len(pl.get('songs', [])))
    for s in pl.get('songs', []):
        sid = s['id']
        if sid not in song_meta:
            song_meta[sid] = {'title': s.get('title'), 'artists': [a.get('name') for a in s.get('artists', [])]}
print('unique songs', len(song_meta))
print('song_ids', sorted(song_meta.keys()))

# fetch reviews for each song by this user, with pagination
user_email = 'as_moore@gmail.com'
all_reviews = {}  # song_id -> list of review dicts
for idx, sid in enumerate(sorted(song_meta.keys())):
    reviews=[]
    j=0
    while True:
        rpage = apis.spotify.show_song_reviews(song_id=sid, user_email=user_email, page_index=j, page_limit=20)
        print('song', idx+1, '/', len(song_meta), 'sid', sid, 'reviews page', j, 'items', len(rpage) if rpage else 0)
        if not rpage:
            break
        reviews.extend(rpage)
        j += 1
        if len(rpage) < 20:
            # safety; still should continue until empty but likely last page
            pass
    all_reviews[sid] = reviews
    if reviews:
        print(' -> existing rating(s):', [rev.get('rating') for rev in reviews], 'review_ids:', [rev.get('song_review_id') for rev in reviews])
    else:
        print(' -> no existing reviews')

# create plan
plan=[]
for sid, meta in song_meta.items():
    reviews = all_reviews.get(sid, [])
    if not reviews:
        plan.append({'song_id': sid, 'title': meta['title'], 'artists': meta['artists'], 'action': 'create', 'target_rating': 5})
    else:
        for rev in reviews:
            rating = rev.get('rating', 0)
            try:
                rating_val = float(rating)
            except Exception:
                rating_val = rating
            if rating_val < 5:
                plan.append({'song_id': sid, 'title': meta['title'], 'artists': meta['artists'], 'action': 'update', 'review_id': rev.get('song_review_id'), 'from_rating': rating, 'target_rating': 5})

print('planned actions', len(plan))
for p in plan:
    print(p)

